import os
from cryptography.hazmat.primitives.ciphers.aead import AESGCM

try:
    import fastgcm
except Exception:
    fastgcm = None

_NT = min(os.cpu_count() or 1, 12)


class Solver:
    def solve(self, problem, **kwargs):
        key = problem["key"]
        nonce = problem["nonce"]
        pt = problem["plaintext"]
        aad = problem["associated_data"]
        if fastgcm is not None and len(nonce) == 12 and len(key) in (16, 24, 32):
            ct, tag = fastgcm.encrypt(key, nonce, pt, aad if aad else b"", _NT)
            return {"ciphertext": ct, "tag": tag}
        c = AESGCM(key).encrypt(nonce, pt, aad)
        return {"ciphertext": c[:-16], "tag": c[-16:]}

