#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <pthread.h>
#include <string.h>
#include <stdint.h>
#include <openssl/evp.h>

typedef struct { uint64_t hi, lo; } be128;

static be128 load(const unsigned char *b){ be128 r=(be128){0,0}; for(int i=0;i<8;i++){r.hi=(r.hi<<8)|b[i]; r.lo=(r.lo<<8)|b[8+i];} return r; }
static void store(be128 x, unsigned char *b){ for(int i=7;i>=0;i--){b[i]=x.hi&0xff;x.hi>>=8;b[8+i]=x.lo&0xff;x.lo>>=8;} }
static be128 gfmul(be128 X, be128 Y){
    be128 Z={0,0}, V=Y;
    for(int i=0;i<128;i++){
        uint64_t bit = i<64 ? (X.hi>>(63-i))&1 : (X.lo>>(127-i))&1;
        if(bit){Z.hi^=V.hi;Z.lo^=V.lo;}
        uint64_t lsb=V.lo&1;
        V.lo=(V.lo>>1)|(V.hi<<63); V.hi>>=1;
        if(lsb) V.hi^=0xe100000000000000ULL;
    }
    return Z;
}
static be128 gfpow(be128 H, uint64_t e){
    be128 r={0x8000000000000000ULL,0}; /* one */
    be128 b=H;
    while(e){ if(e&1) r=gfmul(r,b); b=gfmul(b,b); e>>=1; }
    return r;
}

typedef struct {
    const unsigned char *key; int keylen;
    const unsigned char *nonce;
    const unsigned char *in; unsigned char *out; size_t len;
    uint32_t ctr0;   /* initial counter value */
    unsigned char G[16]; /* tag xor E_K(J0dummy) => (Y_A^L)*H */
    int err;
} job_t;

static const EVP_CIPHER *ctr_cipher(int kl){ return kl==16?EVP_aes_128_ctr():kl==24?EVP_aes_192_ctr():EVP_aes_256_ctr(); }
static const EVP_CIPHER *gcm_cipher(int kl){ return kl==16?EVP_aes_128_gcm():kl==24?EVP_aes_192_gcm():EVP_aes_256_gcm(); }
static const EVP_CIPHER *ecb_cipher(int kl){ return kl==16?EVP_aes_128_ecb():kl==24?EVP_aes_192_ecb():EVP_aes_256_ecb(); }

#define SUB (32*1024)
static void *worker(void *arg){
    job_t *j=(job_t*)arg; j->err=0;
    unsigned char dn[12]={0}; /* dummy nonce, J0 = 0..0 || 00000001 */
    EVP_CIPHER_CTX *g=EVP_CIPHER_CTX_new();
    EVP_CIPHER_CTX *c=NULL;
    int ol;
    if(!EVP_EncryptInit_ex(g,gcm_cipher(j->keylen),NULL,j->key,dn)){j->err=1;goto done;}
    if(j->in){
        unsigned char iv[16]; memcpy(iv,j->nonce,12);
        iv[12]=j->ctr0>>24; iv[13]=j->ctr0>>16; iv[14]=j->ctr0>>8; iv[15]=j->ctr0;
        c=EVP_CIPHER_CTX_new();
        if(!EVP_EncryptInit_ex(c,ctr_cipher(j->keylen),NULL,j->key,iv)){j->err=1;goto done;}
        for(size_t off=0; off<j->len; off+=SUB){
            size_t n = j->len-off<SUB? j->len-off:SUB;
            if(!EVP_EncryptUpdate(c,j->out+off,&ol,j->in+off,(int)n)){j->err=1;goto done;}
            if(!EVP_EncryptUpdate(g,NULL,&ol,j->out+off,(int)n)){j->err=1;goto done;}
        }
    } else {
        /* out holds aad */
        if(j->len && !EVP_EncryptUpdate(g,NULL,&ol,j->out,(int)j->len)){j->err=1;goto done;}
    }
    unsigned char t[16];
    if(!EVP_EncryptFinal_ex(g,t,&ol)){j->err=1;goto done;}
    if(!EVP_CIPHER_CTX_ctrl(g,EVP_CTRL_GCM_GET_TAG,16,t)){j->err=1;goto done;}
    memcpy(j->G,t,16);
done:
    EVP_CIPHER_CTX_free(g); if(c) EVP_CIPHER_CTX_free(c);
    return NULL;
}

static int ecb1(const unsigned char *key,int kl,const unsigned char *in,unsigned char *out){
    EVP_CIPHER_CTX *e=EVP_CIPHER_CTX_new(); int ol, ok;
    ok=EVP_EncryptInit_ex(e,ecb_cipher(kl),NULL,key,NULL) && EVP_CIPHER_CTX_set_padding(e,0) && EVP_EncryptUpdate(e,out,&ol,in,16);
    EVP_CIPHER_CTX_free(e); return ok;
}

static PyObject *encrypt(PyObject *self, PyObject *args){
    Py_buffer kb, nb, pb, ab; int nthreads;
    if(!PyArg_ParseTuple(args,"y*y*y*y*i",&kb,&nb,&pb,&ab,&nthreads)) return NULL;
    PyObject *res=NULL, *ct=NULL;
    int kl=(int)kb.len;
    if((kl!=16&&kl!=24&&kl!=32)||nb.len!=12){PyErr_SetString(PyExc_ValueError,"unsupported");goto out;}
    size_t len=pb.len;
    ct=PyBytes_FromStringAndSize(NULL,len);
    if(!ct) goto out;
    unsigned char *o=(unsigned char*)PyBytes_AS_STRING(ct);
    if(nthreads<1) nthreads=1;
    size_t nblocks=(len+15)/16;
    if(nblocks < (size_t)nthreads*4096) nthreads = nblocks/4096>0? (int)(nblocks/4096):1;
    if(nthreads>64) nthreads=64;
    job_t jobs[65]; pthread_t th[65];
    /* job 0: aad */
    memset(jobs,0,sizeof(jobs));
    jobs[0].key=kb.buf; jobs[0].keylen=kl; jobs[0].in=NULL; jobs[0].out=(unsigned char*)ab.buf; jobs[0].len=ab.len;
    size_t per=nblocks/nthreads, rem=nblocks%nthreads, bstart=0;
    for(int i=0;i<nthreads;i++){
        size_t nb_i=per+((size_t)i<rem);
        job_t *j=&jobs[i+1];
        j->key=kb.buf; j->keylen=kl; j->nonce=nb.buf;
        j->in=(unsigned char*)pb.buf+bstart*16; j->out=o+bstart*16;
        size_t end=(bstart+nb_i)*16; if(end>len) end=len;
        j->len=end-bstart*16;
        j->ctr0=(uint32_t)(2+bstart);
        bstart+=nb_i;
    }
    Py_BEGIN_ALLOW_THREADS
    for(int i=1;i<nthreads;i++) pthread_create(&th[i],NULL,worker,&jobs[i+1]);
    worker(&jobs[0]);
    worker(&jobs[1]);
    for(int i=1;i<nthreads;i++) pthread_join(th[i],NULL);
    Py_END_ALLOW_THREADS
    for(int i=0;i<=nthreads;i++) if(jobs[i].err){PyErr_SetString(PyExc_RuntimeError,"openssl");goto out;}
    {
        unsigned char zero[16]={0}, Hb[16], dj[16]={0}, EJ[16], EJ0[16], J0[16];
        dj[15]=1;
        if(!ecb1(kb.buf,kl,zero,Hb)||!ecb1(kb.buf,kl,dj,EJ)){PyErr_SetString(PyExc_RuntimeError,"ecb");goto out;}
        memcpy(J0,nb.buf,12); J0[12]=0;J0[13]=0;J0[14]=0;J0[15]=1;
        ecb1(kb.buf,kl,J0,EJ0);
        be128 H=load(Hb), ej=load(EJ);
        /* chunks in order: aad (job0), jobs 1..n. a_j = blocks after chunk */
        size_t after=nblocks;
        be128 acc={0,0};
        for(int i=0;i<=nthreads;i++){
            job_t *j=&jobs[i];
            size_t blocks_j=(j->len+15)/16;
            if(i>0) after-=blocks_j;
            be128 G=load(j->G); G.hi^=ej.hi; G.lo^=ej.lo;
            be128 L; L.hi=(uint64_t)(i==0?j->len:0)*8; L.lo=(uint64_t)(i==0?0:j->len)*8;
            if(i>0 && blocks_j==0) continue;
            if(i==0 && j->len==0) continue;
            be128 Ha=gfpow(H,after);
            be128 t1=gfmul(G,Ha);
            be128 t2=gfmul(L,gfmul(Ha,H));
            acc.hi^=t1.hi^t2.hi; acc.lo^=t1.lo^t2.lo;
        }
        be128 Lr; Lr.hi=(uint64_t)ab.len*8; Lr.lo=(uint64_t)len*8;
        be128 t3=gfmul(Lr,H);
        acc.hi^=t3.hi; acc.lo^=t3.lo;
        unsigned char tag[16]; store(acc,tag);
        for(int i=0;i<16;i++) tag[i]^=EJ0[i];
        PyObject *tg=PyBytes_FromStringAndSize((char*)tag,16);
        res=Py_BuildValue("(NN)",ct,tg); ct=NULL;
    }
out:
    Py_XDECREF(ct);
    PyBuffer_Release(&kb);PyBuffer_Release(&nb);PyBuffer_Release(&pb);PyBuffer_Release(&ab);
    return res;
}

